SELECT periodo, especie_codigo,        CASE especie_codigo WHEN '91' THEN 'Auxílio-doença acidentário'             WHEN '92' THEN 'Aposentadoria por invalidez acidentária'             WHEN '93' THEN 'Pensão por morte acidentária'             WHEN '94' THEN 'Auxílio-acidente' WHEN '95' THEN 'Auxílio suplementar'             ELSE 'Outros' END AS especie,        COUNT(*) AS concessoes,        ROUND(AVG(CASE WHEN rmi_salarios_minimos BETWEEN 0.5 AND 50 THEN rmi_salarios_minimos END),3) AS rmi_media FROM {{ source('silver', 'beneficios_acidentarios') }} WHERE acidente_trabalho GROUP BY 1,2,3
